"Abstand Anfang / Ende":"Distanza inizio / fine",
"Abstand Anfang / Ende macht aus der Lasche eine Teillasche. Weitere geschlossene Profile in der Skizze werden zu Ausschnitten in der Platte. Bohrungen und Fenster in einer Lasche: Mitte entlang der Kante (bei einer gebogenen Kante entlang des Bogens), Mitte ab Ende der Biegung, Größe – sie erscheinen auch in der Abwicklung. Geht eine gebogene Kante ohne Knick in ihre Nachbarkante über und haben beide eine Lasche mit gleichem Biegewinkel, laufen die Laschen ohne Freischnitt ineinander über. „Kontur aus Skizze“ schneidet die geschlossenen Profile einer Skizze aus der Lasche: ihr X läuft entlang der Kante, ihr Y in die Lasche hinein, der Nullpunkt liegt am Kantenanfang auf dem Ende der Biegung (verschiebbar).":"Una distanza di inizio / fine trasforma l’aletta in un’aletta parziale. Gli altri profili chiusi dello schizzo diventano ritagli nella piastra. Fori e finestre in un’aletta: centro lungo lo spigolo (su uno spigolo curvo lungo l’arco), centro dalla fine della piega, dimensione – compaiono anche nello sviluppo. Se uno spigolo curvo passa senza angolo nello spigolo adiacente ed entrambi hanno un’aletta con lo stesso angolo di piega, le alette si fondono senza taglio di scarico. «Contorno da schizzo» ritaglia dall’aletta i profili chiusi di uno schizzo: il suo X corre lungo lo spigolo, il suo Y verso l’interno dell’aletta, l’origine si trova all’inizio dello spigolo, sulla fine della piega (spostabile).",
