"Alle Biegungen mit Winkel, Radius, K-Faktor, Zugabe, Länge und Presskraft als Tabelle für die Abkantpresse":"Tutte le pieghe con angolo, raggio, fattore K, sviluppo, lunghezza e forza di pressatura in una tabella per la pressopiegatrice",
"Alle Einstellungen, Symbolleisten-Anpassungen und eigenen Tastenkürzel auf die Vorgaben zurücksetzen?\n\nEigene Werkzeugbibliotheken, Materialien und Vorlagen bleiben erhalten.":"Ripristinare i valori predefiniti di tutte le preferenze, personalizzazioni della barra degli strumenti e scorciatoie da tastiera personali?\n\nLe librerie utensili, i materiali e i modelli personali vengono conservati.",
"Alle Flächen des Merkmals wählen: bei einer Bohrung die Wand (und Senkung, Boden), bei einer Tasche Wände und Boden, bei einem Zapfen Mantel und Stirnfläche. Das Merkmal wandert um X/Y/Z; die alte Stelle wird geschlossen. Geht auch bei importierten STEP-Teilen ohne Verlauf. Beim ersten Mal lädt der große Geometriekern (einige Sekunden).":"Selezionare tutte le facce della feature: per un foro la parete (e svasatura, fondo), per una tasca le pareti e il fondo, per un perno la superficie laterale e la faccia frontale. La feature si sposta di X/Y/Z; la posizione precedente viene chiusa. Funziona anche con pezzi STEP importati senza cronologia. La prima volta si carica il kernel geometrico grande (alcuni secondi).",
"Alle Flächen wählen, die verschwinden sollen (bei einer Tasche Wände und Boden, bei einer Bohrung die Wand, bei einer Verrundung die Rundung). Die Nachbarflächen werden über die Lücke verlängert. Der Schritt rechnet bei Änderungen am Körper mit; beim ersten Mal lädt dafür der große Geometriekern (einige Sekunden).":"Selezioni tutte le facce che devono scomparire (per una tasca pareti e fondo, per un foro la parete, per un raccordo la superficie arrotondata). Le facce adiacenti vengono prolungate sopra la lacuna. Il passo viene ricalcolato alla modifica del corpo; la prima volta viene caricato a tal fine il kernel geometrico completo (alcuni secondi).",
