"Drehen: Das Teil muss rotationssymmetrisch um die Z-Achse liegen. Z0 = Planfläche oben, X = Durchmesser.":"Tornitura: il pezzo deve essere a simmetria di rotazione attorno all'asse Z. Z0 = faccia frontale in alto, X = diametro.",
"Drehen: Drehpunkt anklicken, dann den Winkel mit der Maus zeigen (Vorschau). Esc beendet.":"Ruota: fare clic sul centro di rotazione, poi indicare l'angolo con il mouse (anteprima). Esc termina.",
"Drehen: Durchmesser, auf dem der Revolver schaltet (Okuma, LinuxCNC). 0 = Rohteil-Ø + 200 mm":"Tornitura: diametro a cui la torretta indicizza (Okuma, LinuxCNC). 0 = Ø grezzo + 200 mm",
"Drehen: Elemente wählen, dann Drehpunkt anklicken und den Winkel mit der Maus zeigen (Vorschau); auch als Kopie":"Ruota: selezionare gli elementi, poi fare clic sul punto di rotazione e indicare l'angolo con il mouse (anteprima); anche come copia",
