"Drehen: Z vor der Planfläche, auf dem der Revolver schaltet. 0 = Sicherheitsabstand + 100 mm":"Tornitura: Z davanti alla faccia frontale a cui la torretta indicizza. 0 = distanza di sicurezza + 100 mm",
