"Drehgeschwindigkeit":"Velocità di rotazione vista",
"Drehmaschine mit Y-Achse: Schlüsselflächen, Konturen und Taschen auf der Planfläche fahren mit feststehendem Teil (C fest) in X und Y – genauer als die Polar-Interpolation. Was über den Y-Weg hinausgeht, bleibt bei der Polar-Interpolation.":"Tornio con asse Y: spianature per chiave, contorni e tasche sulla faccia frontale vengono eseguiti con il pezzo fermo (C bloccato) in X e Y, con maggiore precisione rispetto all'interpolazione polare. Ciò che supera la corsa Y resta in interpolazione polare.",
