"Durchzug {0}: Vorbohrung Ø {1} mm wird auf Ø {2} mm aufgeweitet (Faktor {3}) – der Rand reißt dabei meist ein.":"Foro estruso {0}: il preforo Ø {1} mm viene allargato a Ø {2} mm (fattore {3}) – il bordo di solito si strappa.",
"Durchzug {0}: Vorbohrung Ø {1} mm wird auf Ø {2} mm aufgeweitet (Faktor {3}).":"Foro estruso {0}: il preforo Ø {1} mm viene allargato a Ø {2} mm (fattore {3}).",
"Durchzug {0}: liegt {1} mm neben dem Rand (weniger als 2 × Blechdicke) – der Rand beult aus.":"Foro estruso {0}: si trova a {1} mm dal bordo (meno di 2 × lo spessore della lamiera) – il bordo si imbarca.",
"Durchzug {0}: zu hoch für diese Bohrung (die Vorbohrung bliebe ohne Durchmesser)":"Foro estruso {0}: troppo alto per questo foro (il preforo resterebbe senza diametro)",
"Durchzug: der Rand einer runden Bohrung wird zu einem Kragen hochgezogen, etwa als Gewindedurchzug. Der Bohrungsdurchmesser der Skizze ist der fertige Innendurchmesser; im Zuschnitt wird die kleinere Vorbohrung geschnitten.":"Foro estruso: il bordo di un foro tondo viene tirato in alto a formare un colletto, ad esempio come foro estruso per filettatura. Il diametro del foro nello schizzo è il diametro interno finito; nel tranciato viene tagliato il preforo più piccolo.",
