"Eilgang ins Material":"Rapido nel materiale",
"Eilgang nur auf Rückzugs-/Sicherheitshöhe":"Rapido solo alla quota di ritiro/sicurezza",
"Eilgang, Strahl aus":"Rapido, fascio spento",
"Eilgangbewegungen beibehalten":"Mantieni i movimenti in rapido",
"Eilgangrückzug zulassen":"Consenti ritiro in rapido",
