"Ein Fusion-Design mit seiner Zeitachse übernehmen: über das Export-Skript für Fusion":"Importare un design Fusion con la sua timeline: tramite lo script di esportazione per Fusion",
"Ein Gelenk anlegen: ZUSAMMENBAU → „Gelenk“ (J), erst das bewegliche Teil, dann das feste anklicken, Art „Drehgelenk“ oder „Schiebegelenk“.":"Creare un giunto: ASSIEME → «Giunto» (J), fare clic prima sul pezzo mobile, poi su quello fisso, tipo «Rotoidale» o «Prismatico».",
"Ein Rechteck zeichnen: Werkzeug „Rechteck“ (R), zwei Ecken anklicken. Maße kann man direkt eintippen, z. B. 80 und 50.":"Disegnare un rettangolo: strumento «Rettangolo» (R), fare clic su due angoli. Le quote si possono digitare direttamente, ad es. 80 e 50.",
"Ein Rechtsklick in einen Dialog (nicht in ein Eingabefeld) drückt dessen OK-Schaltfläche":"Un clic destro in una finestra di dialogo (non in un campo di immissione) preme il suo pulsante OK",
"Ein anderes gespeichertes Design als Komponente einfügen":"Inserire un altro design salvato come componente",
"Ein eingefügter Satz verschiebt alle folgenden Satznummern – so zählen sie nicht als Änderung":"Un blocco inserito sposta tutti i numeri di blocco successivi – così non contano come modifica",
"Ein fertiges Teil mit Konstruktion und Fräsbearbeitung":"Un pezzo finito con progettazione e fresatura",
"Ein gerollter Rand über 350° schließt sich zum Rohr – das ist so nicht herstellbar":"Un bordo arrotolato oltre 350° si chiude formando un tubo: così non è realizzabile",
"Ein geschlossenes Netz in einen Volumenkörper umwandeln (jedes Dreieck wird eine Fläche)":"Convertire una mesh chiusa in un corpo solido (ogni triangolo diventa una faccia)",
"Ein leeres Design beginnen":"Inizia un progetto vuoto",
"Ein runder Fräser lässt in jeder Innenecke seinen Radius stehen – ein eckiges Gegenstück passt dann nicht hinein. Der Freistich fährt an jeder scharfen Innenecke kurz in die Ecke und zurück.{0}{1}":"Una fresa tonda lascia il proprio raggio in ogni angolo interno: un pezzo complementare a spigolo vivo non vi si inserisce. Lo scarico entra brevemente nell'angolo e torna indietro a ogni angolo interno vivo.{0}{1}",
"Ein verbundener Agent arbeitet am geöffneten Entwurf: Er liest und ändert die Zeitachse, fragt Körper, Volumen und Fehler ab, holt Normteile aus dem Bauteilkatalog, lässt sich ein Bild der Ansicht geben, exportiert STEP oder STL, legt Werkzeuge und Fertigungsoperationen an und gibt das NC-Programm aus – das vor dem ersten Schnitt zu prüfen bleibt. Auf Dateien, Einstellungen und andere Entwürfe hat er keinen Zugriff. Jede Änderung ist ein Schritt, den Strg+Z zurücknimmt.":"Un agente collegato lavora sul progetto aperto: legge e modifica la timeline, interroga corpi, volumi ed errori, preleva parti normalizzate dal catalogo componenti, si fa fornire un'immagine della vista, esporta STEP o STL, crea utensili e operazioni di produzione e genera il programma NC, da verificare prima del primo taglio. Non ha accesso a file, preferenze o altri progetti. Ogni modifica è un passo che Ctrl+Z annulla.",
"Ein zweiter Klick auf die Schaltfläche des Zeichenwerkzeugs schaltet zurück auf Auswählen":"Un secondo clic sul pulsante dello strumento di disegno torna a Seleziona",
"Ein-/Ausblenden":"Mostra/Nascondi",
"Ein-/Ausfahrten und Übergänge":"Ingressi, uscite e transizioni",
"Einblenden":"Mostra",
"Einblendungen":"Sovrapposizioni",
"Eine .f3d-Datei ist ein geschlossenes Format – die Zeitachse darin kann kein anderes Programm lesen. Fusion selbst gibt sie aber über seine Skript-Schnittstelle heraus:":"Un file .f3d è un formato chiuso: nessun altro programma può leggere la timeline al suo interno. Fusion stesso però la fornisce tramite la sua interfaccia di script:",
"Eine .ofab-Datei von diesem Computer öffnen":"Apri un file .ofab da questo computer",
"Eine Bahn entlang jeder Innenecke/Hohlkehle, in der das Werkzeug zwei Flächen zugleich berührt – zum Ausräumen nach dem Schlichten.":"Un percorso lungo ogni spigolo interno/raccordo in cui l'utensile tocca due facce contemporaneamente: per la ripresa del materiale residuo dopo la finitura.",
"Eine Bearbeitung anlegen, z. B. FRÄSEN → „2D-Kontur“ oder „Planfräsen“, Werkzeug wählen, OK.":"Creare una lavorazione, ad es. FRESATURA → «Profilo 2D» o «Spianatura», scegliere un utensile, OK.",
"Eine Bohrung setzen: „Bohrung“ (H), auf die Oberseite klicken, Durchmesser wählen, OK. (Eine Extrusion mit „Ausschneiden“ zählt auch.)":"Inserire un foro: «Foro» (H), fare clic sulla faccia superiore, scegliere un diametro, OK. (Vale anche un'estrusione con «Taglia».)",
"Eine Explosionsansicht braucht mindestens zwei Körper.":"Una vista esplosa richiede almeno due corpi.",
"Eine Explosionsansicht öffnen: „Explosionsansicht“ – „Montageanleitung“ macht daraus eine Seite mit Bildern.":"Aprire una vista esplosa: «Vista esplosa» – «Istruzioni di montaggio» ne ricava una pagina con immagini.",
"Eine Fläche, Bohrung oder einen Zapfen anklicken.":"Fare clic su una faccia, un foro o un perno.",
"Eine Fläche, Bohrung oder einen Zapfen eines Körpers anklicken.":"Fare clic su una faccia, un foro o un perno di un corpo.",
"Eine Konfiguration merkt sich die Ausdrücke aller Parameter unter einem Namen – etwa „kurz“ und „lang“. Ein Klick stellt die Variante wieder her.":"Una configurazione memorizza le espressioni di tutti i parametri con un nome, ad esempio «corto» e «lungo». Un clic ripristina la variante.",
"Eine Platte mit Bohrung und abgerundeten Kanten – Skizze, Extrusion, Bohrung und Verrundung.":"Una piastra con un foro e spigoli arrotondati – schizzo, estrusione, foro e raccordo.",
"Eine STEP-, IGES-, STL-, OBJ-, 3MF- oder PLY-Datei in ein neues Design einfügen":"Inserisci un file STEP, IGES, STL, OBJ, 3MF o PLY in un nuovo progetto",
"Eine Seite":"Un lato",
"Eine Seite mit einem Bild je Montageschritt (Explosion rückwärts), druckbar und als PDF":"Una pagina con un'immagine per ogni passo di montaggio (esploso a ritroso), stampabile e in PDF",
"Eine Variante speichern: VERWALTEN → „Konfigurieren“, Name z. B. dünn.":"Salvare una variante: GESTISCI → «Configura», nome ad es. sottile.",
"Eine der gewählten Kanten oder Flächen wurde nicht mehr gefunden – neu wählen.":"Uno degli spigoli o delle facce selezionati non è più stato trovato – selezionare di nuovo.",
"Einen Bewegungsablauf anlegen: „Bewegungsablauf“, „+ Schritt“, dann ▶ – „Prüfen“ meldet Zusammenstöße mit Zeitpunkt.":"Creare uno studio di movimento: «Studio di movimento», «+ Passo», poi ▶ – «Verifica» segnala le collisioni con il relativo istante.",
