"Erst Schritte anlegen.":"Creare prima dei passi.",
"Erst die Fläche an dem Körper anklicken, der bewegt wird, dann die Zielfläche am anderen Körper. Der Körper wird gedreht und verschoben, bis der erste Klickpunkt auf dem zweiten liegt und die Flächen aufeinander liegen.":"Faccia clic prima sulla faccia del corpo da spostare, poi sulla faccia di destinazione dell'altro corpo. Il corpo viene ruotato e spostato finché il primo punto di clic coincide con il secondo e le facce sono appoggiate l'una sull'altra.",
"Erst die Kante an dem Körper anklicken, der bewegt wird, dann die Zielkante am anderen Körper. Gerade Kanten kommen deckungsgleich aufeinander (Mitte auf Mitte); bei Kreiskanten – Bohrung und Zapfen – werden die Achsen gleich gerichtet und die Mittelpunkte zusammengelegt.":"Faccia clic prima sullo spigolo del corpo da spostare, poi sullo spigolo di destinazione dell'altro corpo. Gli spigoli rettilinei vengono resi coincidenti (centro su centro); per gli spigoli circolari – foro e perno – gli assi vengono allineati e i centri portati a coincidere.",
"Erst ein Setup anlegen.":"Creare prima un setup.",
"Erst ein Setup mit Operationen anlegen.":"Creare prima un setup con operazioni.",
"Erst eine Skizze oder Konstruktionsebene wählen – dann schaut Strg+8 senkrecht darauf.":"Selezioni prima uno schizzo o un piano di costruzione: Ctrl+8 lo guarda poi perpendicolarmente.",
"Erst einen Körper in KONSTRUKTION erstellen oder ein Netz (STL) einfügen.":"Creare prima un corpo in PROGETTAZIONE o inserire una mesh (STL).",
"Erst einen Körper in KONSTRUKTION erstellen.":"Creare prima un corpo in PROGETTAZIONE.",
"Erst einen Namen für das Profil eingeben.":"Inserire prima un nome per il profilo.",
"Erst in eine Vorlage klicken, dann den Platzhalter wählen":"Fare prima clic in un modello, poi scegliere il segnaposto",
"Erste Ecke klicken, dann gegenüberliegende Ecke.":"Cliccare il primo angolo, poi l’angolo opposto.",
"Erstellen":"Crea",
"Erstellt {0}":"Creato {0}",
"Ersten Bogenmittelpunkt, zweiten Bogenmittelpunkt, dann Breite klicken.":"Cliccare il centro del primo arco, il centro del secondo arco, poi la larghezza.",
"Ersten Punkt gewählt – jetzt den zweiten anklicken.":"Primo punto selezionato: ora fare clic sul secondo.",
