"Erzeugt eine neue Fläche im Abstand zu den gewählten Flächen (negativ = nach innen). Der Körper bleibt unverändert.":"Crea una nuova superficie a distanza dalle facce selezionate (negativo = verso l'interno). Il corpo resta invariato.",
"Erzeugt einen Tastzyklus (Heidenhain TCH PROBE 417/412/413/411/410, Fanuc Renishaw G65 P98xx).":"Genera un ciclo di tastatura (Heidenhain TCH PROBE 417/412/413/411/410, Fanuc Renishaw G65 P98xx).",
"Es braucht einen Körper – falls keiner da ist: Datei → Beispiele, oder zuerst „Erstes Teil“.":"Serve un corpo – se non ce n'è nessuno: File → Esempi, oppure prima «Primo pezzo».",
"Es braucht einen Körper – falls noch keiner da ist, zuerst die Aufgabe „Erstes Teil“ machen.":"Serve un corpo – se non ce n'è ancora nessuno, svolgere prima la lezione «Primo pezzo».",
"Es braucht mindestens zwei Körper (z. B. zwei Extrusionen mit „Neuer Körper“).":"Servono almeno due corpi (ad es. due estrusioni con «Nuovo corpo»).",
