"Fläche an ihren Rändern tangential weiterführen":"Prolunga una faccia in tangenza ai suoi bordi",
"Fläche anklicken – die Bohrung entsteht mit":"Fare clic su una faccia – il foro viene creato insieme",
"Fläche anklicken: an jedem Klickpunkt entsteht die Durchgangsbohrung für die Schraube (ISO 273, Reihe mittel) durch alle Teile, die dort aufeinanderliegen – für Senkschrauben mit 90°-Senkung, für Zylinderschrauben auf Wunsch mit Senkbohrung (DIN 974-1, Reihe 1) so tief wie der Kopf. Die Schraube sitzt gleich darin. Bohrung und Schraube lassen sich danach im Verlauf ändern.":"Fare clic su una faccia: in ogni punto selezionato viene creato il foro passante per la vite (ISO 273, serie media) attraverso tutti i pezzi sovrapposti in quel punto – con svasatura a 90° per le viti a testa svasata e, su richiesta, con lamatura (DIN 974-1, serie 1) profonda quanto la testa per le viti a testa cilindrica. La vite viene inserita subito nel foro. Foro e vite possono poi essere modificati nella timeline.",
"Fläche eines Körpers anklicken: ihr Rand kommt als Kontur in die Skizze. Eine Kante anklicken projiziert nur diese Kante (Kreise bleiben Kreise). Projizierte Geometrie ist violett.":"Cliccare una faccia di un corpo: il suo bordo entra nello schizzo come contorno. Cliccando uno spigolo si proietta solo quello spigolo (i cerchi restano cerchi). La geometria proiettata è viola.",
"Fläche ersetzen":"Sostituisci faccia",
"Fläche ersetzen: eine ebene Fläche auf eine andere Ebene legen – der Körper wächst oder wird gekürzt":"Sostituisci faccia: spostare una faccia piana su un altro piano – il corpo si allunga o si accorcia",
"Fläche extrudieren":"Estrudi faccia",
"Fläche gewählt – Skizze, Drücken/Ziehen (Q), Extrusion (E), Bohrung (H) oder Schale nimmt sie. Umschalt/Strg + Klick: weitere Flächen.":"Faccia selezionata – la useranno Schizzo, Premi/Tira (Q), Estrusione (E), Foro (H) o Guscio. Maiusc/Ctrl + clic: altre facce.",
"Fläche hinter den Fenstern – gilt, wenn oben das Design „Eigenes“ gewählt ist":"Sfondo dietro le finestre – vale se sopra è scelto il tema «Personalizzato»",
"Fläche löschen":"Elimina faccia",
"Fläche löschen: Bohrungen, Taschen, Verrundungen oder Fasen entfernen – die Nachbarflächen schließen die Lücke":"Elimina faccia: rimuovere fori, tasche, raccordi o smussi – le facce vicine chiudono il vuoto",
"Fläche löschen: OK schließt die Lücke. Den ganzen Körper entfernt Entf, wenn er im Browser gewählt ist.":"Elimina faccia: OK chiude la lacuna. Canc rimuove l’intero corpo quando è selezionato nel browser.",
