"Flächen anklicken, die versetzt werden (erneut klicken entfernt).":"Cliccare le facce da offsettare (un nuovo clic le rimuove).",
"Flächen eine Wandstärke geben":"Dai uno spessore alle facce",
"Flächen im Modell":"Facce nel modello",
"Flächen mit gemeinsamen Kanten werden zu einer verbunden. Ist die Hülle rundum geschlossen, entsteht ein Volumenkörper (danach normal weiterbearbeitbar). Lücken größer als die Toleranz bleiben offen.":"Le superfici con spigoli in comune vengono unite in una sola. Se l'involucro è completamente chiuso, si ottiene un corpo solido (poi modificabile normalmente). Le lacune maggiori della tolleranza restano aperte.",
