"Fährt alle scharfen Außenkanten ab, die von oben erreichbar sind, und bricht sie um die Entgrattiefe – mit dem Fasenfräser als Fase (Werkzeugachse senkrecht, Spitze außerhalb der Kante), mit dem Kugel-/Lollipop-Fräser gerundet.":"Percorre tutti gli spigoli esterni vivi raggiungibili dall'alto e li rompe della profondità di sbavatura: con la fresa per smussare come smusso (asse utensile verticale, punta fuori dallo spigolo), con la fresa sferica/lollipop arrotondati.",
"Führungszapfen-Ø":"Ø perno di guida",
