"Für Dateien aus Programmen, in denen Y nach oben zeigt: das Netz wird aufgerichtet und auf Z = 0 gestellt":"Per file di programmi in cui Y punta verso l'alto: la mesh viene raddrizzata e posta su Z = 0",
"Für Gewindebohren einen Gewindebohrer wählen":"Selezionare un maschio per la maschiatura",
"Für Gewindefräsen einen Gewindefräser wählen":"Selezionare una fresa per filettare per la fresatura di filettature",
