"Für Touchpads: Scrollen verschiebt die Ansicht, Auseinanderziehen (oder Strg + Mausrad) zoomt":"Per i touchpad: lo scorrimento sposta la vista, l'allargamento delle dita (o Ctrl + rotellina) fa lo zoom",
"Für V-Gravur einen Fasenfräser (V) wählen":"Selezionare una fresa per smussi (V) per l'incisione a V",
"Für den Steuerungszyklus entlang einer Linie die Nutbreite angeben":"Per il ciclo del controllo lungo una linea indicare la larghezza della cava",
"Für diese Strategie nicht geeignet":"Non adatto a questa strategia",
"Für eine Bohrung Ø {0} mm gibt es in dieser Reihe keine passende Schraube.":"Per un foro Ø {0} mm non esiste una vite adatta in questa serie.",
"Für schräge Richtungen eine Konstruktionsachse anlegen (durch zwei Punkte, einen Zylinder oder zwei Ebenen) – sie erscheint dann hier als Richtung.":"Per direzioni oblique creare un asse di costruzione (per due punti, un cilindro o due piani): comparirà qui come direzione.",
"Für wirbelndes Fräsen entlang einer Linie die Nutbreite angeben":"Per la fresatura trocoidale lungo una linea indicare la larghezza della scanalatura",
