"Gefräst wird von unten nach oben im Gleichlauf. M6 = Nenn-Ø 6, Steigung 1; M8 = 8 / 1,25; M10 = 10 / 1,5.":"La fresatura procede dal basso verso l'alto in concordanza. M6 = Ø nominale 6, passo 1; M8 = 8 / 1,25; M10 = 10 / 1,5.",
