"Gelenkursprung: Bohrung, Zapfen oder Fläche anklicken (mehrere nacheinander möglich).":"Origine del giunto: fare clic su un foro, un perno o una faccia (è possibile sceglierne più di uno in sequenza).",
"Gelenkursprünge ({0})":"Origini giunto ({0})",
"Gelenkursprünge neu wählen":"Riselezionare le origini del giunto",
"Gemeinsame Schnittkanten nur einmal schneiden":"Tagliare una sola volta i bordi di taglio comuni",
"Gemeinsame Schnittkanten: liegen zwei Zuschnitte genau eine Schnittfuge auseinander (beim Schachteln als Abstand die Schnittfuge eintragen), fällt ihre Bahn auf der gemeinsamen Kante zusammen und wird nur einmal geschnitten. Der Anschnitt liegt nie in einem Nachbarteil: ist neben einer Kontur kein freier Abfall, wird auf der Kontur eingestochen. Nach „Vorschau“ zeigt ein Bild je Tafel die Bahn, bevor die Dateien gespeichert werden.":"Bordi di taglio comuni: se due sagome distano esattamente una larghezza di taglio (nell'annidamento inserire la larghezza di taglio come distanza), i loro percorsi coincidono sul bordo comune e vengono tagliati una sola volta. L'ingresso non cade mai in un pezzo vicino: se accanto a un contorno non c'è scarto libero, si fora sul contorno. Dopo «Anteprima», un'immagine per foglio mostra il percorso prima che i file vengano salvati.",
