"Geometriekern: OpenCascade (über replicad) · Darstellung: three.js · Einstellungen werden auf diesem Rechner gespeichert.":"Kernel geometrico: OpenCascade (tramite replicad) · Rendering: three.js · Le preferenze vengono salvate su questo computer.",
