"Gerade (radial)":"Retta (radiale)",
"Gerade Linien der Skizze, die zu keinem Profil gehören (auch Hilfslinien). Biegung: die Linie ist die Mitte der Biegezone, die Skizze dort der Zuschnitt – das größte Stück der Platte bleibt liegen, alles jenseits der Linie schwenkt mit seinen Laschen mit. Die Linie gilt über die ganze Platte. Sicke: eine Rippe entlang der Linie, im Querschnitt und an den Enden rund; das Blech behält seine Dicke.":"Linee rette dello schizzo che non appartengono ad alcun profilo (anche linee ausiliarie). Piega: la linea è il centro della zona di piega e lo schizzo lì è il tranciato – la parte più grande della piastra resta ferma, tutto ciò che sta oltre la linea ruota insieme alle sue flange. La linea vale per l'intera piastra. Nervatura: una costola lungo la linea, tonda nella sezione e alle estremità; la lamiera mantiene il suo spessore.",
"Gerade Nuten (Langloch oder Linie mit Nutbreite) gehen als Nutzyklus der Steuerung heraus.":"Le cave rettilinee (asola o linea con larghezza di cava) escono come ciclo di cava del controllo.",
