"Geschafft! Das Teil steht in der Zeitleiste unten – ein Doppelklick auf einen Schritt ändert ihn nachträglich. Weiter geht es mit „Maße als Parameter“ oder „Vom Teil zum NC-Programm“.":"Fatto! Il pezzo si trova nella timeline in basso – un doppio clic su un passo permette di modificarlo in seguito. Si prosegue con «Quote come parametri» o «Dal pezzo al programma NC».",
"Geschlossen":"Chiuso",
"Geschlossen (Gehrung)":"Chiuso (a sguscio)",
"Geschlossen: Laschen an zwei Nachbarkanten laufen bis zur Winkelhalbierenden der Ecke und lassen dort den Spalt frei. Die Eckfreistellung sitzt, wo sich die Biegezonen kreuzen – in der Abwicklung und im gebogenen Teil. Auch eine Lasche an einer gebogenen Kante wird an einer echten Ecke auf Gehrung geschnitten (dort ohne Eckfreistellung).":"Chiuso: le flange su due spigoli adiacenti arrivano fino alla bisettrice dell'angolo e lì lasciano libera la luce. Lo scarico d'angolo si trova dove si incrociano le zone di piega – nello sviluppo e nella parte piegata. Anche una flangia su uno spigolo curvo viene tagliata a 45° (a sghembo) in un angolo vero (lì senza scarico d'angolo).",
"Geschlossene Kette {0}":"Catena chiusa {0}",
"Geschlossene Profile begrenzen den Bereich.":"I profili chiusi delimitano l'area.",
"Geschlossene Profile der aktiven Skizze farbig füllen":"Riempi a colori i profili chiusi dello schizzo attivo",
"Geschlossene Profile werden zu ebenen Flächen – z. B. Deckel und Boden, um Flächen anschließend zu einem Körper zusammenzufügen.":"I profili chiusi diventano superfici piane – ad es. coperchio e fondo, per cucire poi le superfici in un corpo.",
