"Gewindebohrung im untersten Teil":"Foro filettato nel componente inferiore",
"Gewindebohrung im untersten Teil: die Durchgangsbohrung endet, wo das unterste Teil beginnt; dort entsteht das Kernloch mit Gewinde – drei Gewindegänge tiefer, als die Schraube reicht, oder durch das ganze Teil. Liegt nur ein Teil unter dem Punkt, bekommt es das Gewinde von der Fläche an. „Länge passend zur Einschraubtiefe“ nimmt die nächste Länge der Reihe, mit der die Schraube etwa so tief im Gewinde sitzt, wie ihr Gewinde dick ist (Richtwert für Stahl) – aber nie länger, als das Teil dick ist.":"Foro filettato nel pezzo più in basso: il foro passante termina dove inizia il pezzo più basso; lì viene creato il foro di nocciolo con filettatura, tre passi di filetto più in profondità di quanto arrivi la vite, oppure attraverso tutto il pezzo. Se sotto il punto si trova un solo pezzo, la filettatura parte dalla sua faccia. «Lunghezza adatta alla profondità di avvitamento» sceglie la lunghezza successiva della serie con cui la vite è avvitata nel filetto circa quanto il suo diametro (valore indicativo per l'acciaio), ma mai più lunga dello spessore del pezzo.",
"Gewindebohrung {0} – Einschraubtiefe nur {1} mm":"foro filettato {0} – profondità di avvitamento solo {1} mm",
"Gewindebohrung {0}, Einschraubtiefe {1} mm":"foro filettato {0}, profondità di avvitamento {1} mm",
"Gewindebohrung: gebohrt wird das Kernloch; das Gewinde erscheint als Gewindedarstellung am Modell und mit seinem Namen in der Zeichnung.":"Foro filettato: viene eseguito il foro per maschiatura; la filettatura appare come rappresentazione di filettatura sul modello e con la sua designazione nel disegno.",
