"Gleiche Durchmesser ergeben ein Rohr, verschiedene einen Kegelstumpf. Die Abwicklung wird auf der neutralen Faser gerechnet (Innenfläche + K-Faktor × Blechdicke); beim Runden liegt sie näher an der Blechmitte als beim Abkanten – üblich ist ein K-Faktor von 0,45 bis 0,5. Mit einer Blechregel gelten deren Dicke und K-Faktor. Der Nahtspalt bleibt am größeren Durchmesser offen (0 = stumpf gestoßen, im Körper dann ein Schlitz von 0,01 mm).":"Diametri uguali danno un tubo, diametri diversi un tronco di cono. Lo sviluppo viene calcolato sulla fibra neutra (superficie interna + fattore K × spessore lamiera); nella calandratura si trova più vicino alla mezzeria della lamiera che nella piegatura – un fattore K da 0,45 a 0,5 è usuale. Con una regola lamiera valgono il suo spessore e il suo fattore K. Il gioco di giunzione resta aperto sul diametro maggiore (0 = testa a testa, nel corpo allora una fessura di 0,01 mm).",
"Gleiche Länge oder gleichen Radius erzwingen":"Imponi uguale lunghezza o uguale raggio",
"Gleicher Abstand":"Distanza uguale",
"Gleichlauf":"Concordante",
"Gleichmäßige Dreiecke dieser Größe: lange Kanten werden geteilt, danach wird auf die Dreieckszahl eines gleichmäßigen Netzes reduziert. Gut vor dem Glätten oder Formen von Scans.":"Triangoli uniformi di questa dimensione: gli spigoli lunghi vengono divisi, poi la mesh viene ridotta al numero di triangoli di una mesh uniforme. Utile prima di levigare o modellare scansioni.",
