"Halbzeug: Nennmaße der Norm, auf jede Länge zugeschnitten. Nicht jede Paarung von Maß und Wanddicke ist bei jedem Händler am Lager. Ein Rohr entlang einer Skizzenlinie – auch um Ecken und Bögen – legt der Befehl „Rohr“ an.":"Semilavorato: misure nominali della norma, tagliato a qualsiasi lunghezza. Non ogni combinazione di misura e spessore di parete è a magazzino presso ogni rivenditore. Un tubo lungo una linea dello schizzo, anche attorno a spigoli e archi, viene creato dal comando «Tubo».",
