"Heidenhain: an der Steuerung die Datenübertragung über Ethernet freigeben (wie für TNCremo, LSV2, Port 19000); Standardordner TNC 640 TNC:\\nc_prog\\, iTNC 530 TNC:\\. FTP: Port 21, Ordner z. B. /_N_WKS_DIR oder /NC. Netzwerkordner: Pfad wie \\\\MASCHINE\\NC oder Z:\\NC. DNC: Wandler als TCP-Server (raw), meist Port 4001; an der Steuerung „Abarbeiten extern“, DNC oder TAPE starten.":"Heidenhain: abilitare sul controllo il trasferimento dati via Ethernet (come per TNCremo, LSV2, porta 19000); cartella predefinita TNC 640 TNC:\\nc_prog\\, iTNC 530 TNC:\\. FTP: porta 21, cartella ad es. /_N_WKS_DIR oppure /NC. Cartella di rete: percorso come \\\\MASCHINE\\NC o Z:\\NC. DNC: convertitore come server TCP (raw), di solito porta 4001; sul controllo avviare «Esecuzione esterna», DNC o TAPE.",
