"ISO metrisch. Außengewinde (Tiefe 0,6134 × P) oder mit einem Innenwerkzeug Innengewinde (vom Kern-Ø D − 1,0825 × P bis zum Nenn-Ø). Ausgabe G32/G33.":"ISO metrica. Filettatura esterna (profondità 0,6134 × P) oppure, con un utensile interno, filettatura interna (dal Ø di nocciolo D − 1,0825 × P fino al Ø nominale). Uscita G32/G33.",
