"Im Eingabefeld, in dem der Cursor steht: Mausrad oder ↑ ↓ ändern den Wert um 1 (mit Umschalt um 10, mit Alt um 0,1)":"Nel campo in cui si trova il cursore: la rotellina o ↑ ↓ cambiano il valore di 1 (con Maiusc di 10, con Alt di 0,1)",
