"Im Programm (dieser Computer)":"Nel programma (questo computer)",
"Im Programm: die Designs liegen im Speicher des Programms auf diesem Computer. Ordner: jedes Design liegt zusätzlich als .ofab-Datei in einem Ordner Ihrer Wahl, z. B. auf einem Netzlaufwerk oder in einem synchronisierten Ordner. Die gespeicherten Versionen bleiben im Programm.":"Nel programma: i design si trovano nella memoria del programma su questo computer. Cartella: ogni design è inoltre un file .ofab in una cartella a vostra scelta, ad es. su un'unità di rete o in una cartella sincronizzata. Le versioni salvate restano nel programma.",
"Im Setup gewählt, bestimmt die Maschine Postprozessor, Eilgang (Laufzeit) und die Grenzwert-Prüfungen.":"Se selezionata nel setup, la macchina determina postprocessore, rapido (tempo di esecuzione) e controlli dei limiti.",
"Im Spiegelbild läuft das Werkzeug andersherum: aus Gleichlauf wird dort Gegenlauf. Die Radiuskorrektur der Steuerung wechselt die Seite mit.":"Nell'immagine speculare l'utensile gira al contrario: la fresatura concordante diventa discordante. Anche la correzione del raggio del controllo cambia lato.",
"Import":"Importa",
"Import der Fusion-Zeitachse abgebrochen: {0}":"Importazione della timeline di Fusion interrotta: {0}",
"Import fehlgeschlagen:":"Importazione non riuscita:",
