"Importieren":"Importa",
"Importieren …":"Importa …",
"Importiert":"Importato",
"Importierte Körper sind ohne Konstruktionshistorie, lassen sich aber weiterbearbeiten (Verrundung, Fase, Ausschneiden …) und für CAM verwenden. Mit „Y-Achse oben“ werden Modelle aus Programmen mit Y nach oben richtig hingestellt.":"I corpi importati non hanno cronologia di progettazione, ma possono essere ulteriormente modificati (raccordo, smusso, taglio …) e usati per il CAM. Con «Asse Y verso l'alto» i modelli provenienti da programmi con Y verso l'alto vengono orientati correttamente.",
"In Bibliothek":"Nella libreria",
"In Dokument kopieren":"Copia nel documento",
"In XY zentrieren":"Centra in XY",
"In Zeitachse suchen":"Cerca nella timeline",
"In der Bibliothek (alle Projekte)":"Nella libreria (tutti i progetti)",
"In die Skizze einfügen":"Inserisci nello schizzo",
"In die Vorlage einfügen":"Inserisci nel modello",
"In die Zwischenablage kopiert":"Copiato negli appunti",
"In diese Bibliothek kann nicht eingefügt werden – Dokument oder eigene Bibliothek wählen.":"Impossibile incollare in questa libreria – scegliere il documento o una libreria personale.",
"In diesem Setup sind Spannmittel gewählt: dann bleibt es beim vollständigen Rückzug.":"In questo setup sono selezionati dei sistemi di serraggio: rimane quindi il ritiro completo.",
"In welcher Einheit STL-, OBJ-, 3MF- und PLY-Dateien ohne Angabe gelesen werden (je Netz änderbar)":"Unità in cui vengono letti i file STL, OBJ, 3MF e PLY privi di indicazione (modificabile per ogni mesh)",
"In welcher Form „An Slicer senden“ die Teile übergibt":"In quale forma «Invia allo Slicer» passa i pezzi",
"In „{0}“ kopieren":"Copia in «{0}»",
"In „{0}“ wurden keine Bohrungen gefunden (gesucht: runde Durchgangs- und Sacklöcher, auch mit Senkung). Bei Netzen vorher „Netz → Körper“ – dort werden Bohrungen zu echten Zylindern.":"In «{0}» non sono stati trovati fori (cercati: fori tondi passanti e ciechi, anche con svasatura). Per le mesh usare prima «Mesh → corpo» – lì i fori diventano veri cilindri.",
"In-Canvas-Rendern":"Rendering nella vista",
