"Innendrehen":"Tornitura interna",
"Innendrehen Ø8,9":"Tornitura interna Ø8,9",
"Innendurchmesser":"Diametro interno",
"Innenecken mit einer Bahn nachfahren, der Fräser neigt sich zur Fläche":"Segui gli angoli interni con un'unica passata, la fresa si inclina verso la superficie",
"Innenecken und Hohlkehlen mit einer Bahn nachfahren":"Segui angoli interni e raccordi con un'unica passata",
