"Innengewindemeißel 60°":"Utensile per filettatura interna 60°",
"Innenkühlung":"Raffreddamento interno",
"Innenkühlung (durch Werkzeug)":"Raffreddamento interno (attraverso l'utensile)",
"Innenmaß (ab Innenfläche der Platte)":"Misura interna (dalla faccia interna della piastra)",
"Innenradius":"Raggio interno",
