"Interferenz braucht mindestens zwei Körper.":"L'interferenza richiede almeno due corpi.",
"Inventor (Mitte verschieben, Umschalt+Mitte drehen)":"Inventor (sposta con centrale, Maiusc+centrale ruota)",
"Invers Verschleiß":"Usura inversa",
"Invertieren (helle Linien auf dunklem Grund)":"Inverti (linee chiare su sfondo scuro)",
