"JSON kopieren":"Copia JSON",
"Je Operation zwei Q-Parameter am Programmanfang: der erste verschiebt die Tiefe (DL, + = weniger tief), der zweite das seitliche Aufmaß (DR, + = mehr Aufmaß; wirkt nur bei Radiuskorrektur an der Steuerung RL/RR). An der Maschine eine Zahl ändern statt Sätze suchen.":"Due parametri Q per operazione all'inizio del programma: il primo sposta la profondità (DL, + = meno profondo), il secondo il sovrametallo laterale (DR, + = più sovrametallo; agisce solo con correzione raggio nel controllo RL/RR). Sulla macchina si cambia un numero invece di cercare blocchi.",
"Je Skizze die erste Kurve – offen oder geschlossen. Die Kurven werden mit einer Haut verbunden (Fläche ohne Dicke).":"La prima curva di ogni schizzo – aperta o chiusa. Le curve vengono unite da una pelle (superficie senza spessore).",
"Je Tafel eine Datei. Die Bahn läuft um die halbe Schnittfuge (beim Fräsen den halben Fräser) neben dem Umriss im Abfall; Ausschnitte kommen vor dem Umriss ihres Teils, jede Kontur beginnt mit einem Anschnitt aus dem Abfall. Kiemenschlitze werden auf ihrer Linie geschnitten. Haltestege: so viele Stellen je Umriss bleiben stehen (Laser, Plasma, Wasserstrahl: der Strahl setzt dort aus; Fräsen: der Fräser hebt auf halbe Blechdicke), Umrisse unter 40 mm Länge bekommen keine. „Steuerung“ legt fest, womit der Strahl ein- und ausgeschaltet wird; die Einstechzeit steht als G4 im Programm, außer die Steuerung sticht selbst ein. Nullpunkt ist die linke untere Ecke der Tafel, beim Fräsen Z0 die Blechoberseite. Das Programm vor dem Einsatz an der Maschine oder in einem NC-Simulator prüfen.":"Un file per foglio. Il percorso corre nello scarto accanto al profilo, spostato di metà larghezza di taglio (in fresatura, metà fresa); i ritagli vengono prima del profilo del loro pezzo, ogni contorno inizia con un ingresso dallo scarto. Le feritoie vengono tagliate sulla loro linea. Ponticelli: questo numero di punti per profilo resta non tagliato (laser, plasma, getto d'acqua: il fascio si interrompe lì; fresatura: la fresa si solleva a metà dello spessore della lamiera); i profili più corti di 40 mm non ne hanno. «Controllo» stabilisce come il fascio viene acceso e spento; il tempo di foratura compare come G4 nel programma, a meno che il controllo non fori da sé. L'origine è l'angolo in basso a sinistra del foglio; in fresatura Z0 è la superficie superiore della lamiera. Verificare il programma sulla macchina o in un simulatore NC prima dell'uso.",
"Je Werkzeug alle Teile (weniger Werkzeugwechsel)":"Tutti i pezzi per utensile (meno cambi utensile)",
"Jede Achse einzeln: Kante, Ecke, Fläche oder Bohrung anklicken. Nicht gesetzte Achsen kommen vom Rohteilpunkt.":"Ogni asse singolarmente: fare clic su uno spigolo, un angolo, una faccia o un foro. Gli assi non impostati derivano dal punto del grezzo.",
"Jede Bohrung wird mit ihren Koordinaten einzeln angefahren (X/Y je Bohrung) – kein Lochkreis- oder Rastermuster.":"Ogni foro viene raggiunto singolarmente con le sue coordinate (X/Y per foro) – nessuno schema a cerchio di fori o a griglia.",
"Jede Operation als Unterprogramm (LBL) am Programmende, Aufruf mit CALL LBL":"Ogni operazione come sottoprogramma (LBL) a fine programma, chiamata con CALL LBL",
"Jede Variante berechnen und als STEP, STL oder 3MF speichern (eine ZIP-Datei)":"Calcolare ogni variante e salvarla come STEP, STL o 3MF (un file ZIP)",
"Jeder Kreis der Skizze ist ein Bohrungsmittelpunkt. Gebohrt wird entgegen der Skizzennormalen (ins Material).":"Ogni cerchio dello schizzo è il centro di un foro. La foratura avviene in direzione opposta alla normale dello schizzo (nel materiale).",
"Jeder Kreis der Skizze wird um die Mitte (in Skizzenkoordinaten) gedreht wiederholt – ein Kreis im Abstand des Teilkreisradius ergibt einen Lochkreis.":"Ogni cerchio dello schizzo viene ripetuto ruotandolo attorno al centro (in coordinate dello schizzo): un cerchio alla distanza del raggio primitivo produce una circonferenza di fori.",
"Jeder Kreis der Skizze wird zum Raster: Abstände in X und Y der Skizze (auch negativ).":"Ogni cerchio dello schizzo diventa una griglia: distanze in X e Y dello schizzo (anche negative).",
"Jeder Schritt ist gegen Volumen, Körperzahl und Schwerpunkt aus Fusion geprüft. Skizzen kommen mit festen Maßen, ohne Abhängigkeiten.":"Ogni passo è verificato rispetto a volume, numero di corpi e baricentro di Fusion. Gli schizzi arrivano con quote fisse, senza vincoli.",
"Jeder sichtbare Körper wird ein Glied mit Netz (STL, in Metern), Masse und Trägheit, jedes Gelenk ein Gelenk mit Achse und Grenzen. Die jetzige Stellung ist die Nullstellung. Mit einem Paketnamen stehen die Netze im URDF als package://Name/meshes/…, sonst als relativer Pfad.":"Ogni corpo visibile diventa un membro (link) con mesh (STL, in metri), massa e inerzia, ogni giunto diventa un giunto (joint) con asse e limiti. La posizione attuale è la posizione zero. Con un nome di pacchetto le mesh compaiono nell'URDF come package://Name/meshes/…, altrimenti come percorso relativo.",
"Jedes # im Skizzentext wird durch die Nummer ersetzt, mit Nullen aufgefüllt (SN-#### → SN-{0}). Bei mehreren Teilen in einer Aufspannung bekommt jedes Teil die nächste Nummer: {1}{2}.":"Ogni # nel testo dello schizzo viene sostituito dal numero, completato con zeri (SN-#### → SN-{0}). Con più pezzi in un piazzamento ogni pezzo riceve il numero successivo: {1}{2}.",
"Jedes Design liegt als .ofab-Datei im Ordner und wird nach jeder Änderung neu geschrieben. Dateien, die dort hineinkopiert werden, erscheinen hier.":"Ogni design è un file .ofab nella cartella e viene riscritto dopo ogni modifica. I file copiati al suo interno compaiono qui.",
"Jedes Teil hat seinen eigenen Nullpunkt in der Steuerung (G54, G55 … bzw. Bezugspunkt-Nummer in der Tabelle – Heidenhain Zyklus 247). Alle Nullpunkte vorher an der Maschine setzen.":"Ogni pezzo ha la propria origine nel controllo (G54, G55 … o numero dell'origine nella tabella – Heidenhain ciclo 247). Impostare prima tutte le origini sulla macchina.",
"Jedes eigene Maß und jeder Toleranzrahmen bekommt eine Nummer in einem Kreis. Die Liste enthält Nennmaß, Toleranz, Höchst- und Mindestmaß und Felder für den Istwert. Maße ohne eigene Toleranz bekommen die Allgemeintoleranz.":"Ogni quota propria e ogni riquadro di tolleranza riceve un numero in un cerchio. L'elenco contiene quota nominale, tolleranza, quota massima e minima e campi per il valore reale. Le quote senza tolleranza propria ricevono la tolleranza generale.",
"Jetzigen Stand festhalten":"Salva lo stato attuale",
"Jetzt einen Punkt auf dem zweiten Schenkel.":"Ora un punto sul secondo lato.",
"Jetzt festhalten":"Salva ora",
"Jetzt jede Richtung einmal bis zum Anschlag: schieben, ziehen, drücken, kippen, drehen (10 s) …":"Ora ogni direzione una volta fino a fondo corsa: spostare, tirare, premere, inclinare, ruotare (10 s) …",
