"K-Faktor {0} liegt außerhalb des üblichen Bereichs 0,25 … 0,5 – der Zuschnitt weicht dann meist vom gebogenen Teil ab.":"Il fattore K {0} è al di fuori dell'intervallo usuale 0,25 … 0,5: il tranciato di solito si discosta dal pezzo piegato.",
