"KI-Agenten verbinden sich mit der Desktop-App von WerkFab (Windows, Linux, macOS) über das Model Context Protocol (MCP). Im Browser gibt es dafür keinen Anschluss.":"Gli agenti IA si collegano all'app desktop di WerkFab (Windows, Linux, macOS) tramite il Model Context Protocol (MCP). Nel browser non c'è una porta per questo.",
"KI-Agenten zulassen":"Consenti agenti IA",
