"Kalibrieren abgebrochen.":"Calibrazione annullata.",
"Kalibrieren …":"Calibra …",
"Kalibrieren: einen Abstand größer als 0 angeben.":"Calibra: indichi una distanza maggiore di 0.",
"Kalibrieren: ersten Punkt im Bild anklicken (Esc bricht ab).":"Calibra: faccia clic sul primo punto dell'immagine (Esc annulla).",
"Kalibrieren: wirklicher Abstand der beiden Punkte (mm)":"Calibra: distanza reale tra i due punti (mm)",
"Kalibrieren: zwei Punkte im Bild anklicken, deren Abstand bekannt ist, und den wirklichen Abstand eingeben – das Bild bekommt den richtigen Maßstab.":"Calibra: faccia clic su due punti dell'immagine di cui è nota la distanza e inserisca la distanza reale – l'immagine assume la scala corretta.",
"Kalibrieren: zweiten Punkt im Bild anklicken (Esc bricht ab).":"Calibra: faccia clic sul secondo punto dell'immagine (Esc annulla).",
"Kalibrierung":"Calibrazione",
