"Kamera":"Camera",
"Kamera ohne Perspektive (ein/aus): parallele Kanten bleiben parallel":"Camera senza prospettiva (sì/no): i bordi paralleli restano paralleli",
"Kante":"Spigolo",
"Kante als Kreis projiziert":"Spigolo proiettato come cerchio",
"Kante am bewegten Körper gewählt":"Spigolo del corpo mobile selezionato",
"Kante im Blatt anklicken …":"Fare clic su uno spigolo del foglio …",
"Kante projiziert":"Spigolo proiettato",
"Kante {0} (Bogen R{1}, {2} mm)":"Spigolo {0} (arco R{1}, {2} mm)",
"Kante {0} (Kreis R{1}, {2} mm)":"Spigolo {0} (cerchio R{1}, {2} mm)",
"Kante {0} ({1} mm)":"Spigolo {0} ({1} mm)",
"Kante {0} ist zu kurz für eine Lasche":"Lo spigolo {0} è troppo corto per una flangia",
"Kante {0}: Biegewinkel über 180° ist nicht herstellbar.":"Spigolo {0}: un angolo di piegatura superiore a 180° non è realizzabile.",
"Kante {0}: Lasche an einer gebogenen Kante – ihr Rand wird beim Umformen um {1} % gestaucht (Faltengefahr); der Zuschnitt ist dort eine Näherung.":"Spigolo {0}: flangia su uno spigolo curvo – il suo bordo viene compresso del {1} % durante la formatura (rischio di pieghe); il ritaglio è qui un'approssimazione.",
"Kante {0}: Lasche an einer gebogenen Kante – ihr Rand wird beim Umformen um {1} % gestreckt (Rissgefahr); der Zuschnitt ist dort eine Näherung.":"Spigolo {0}: flangia su uno spigolo curvo – il suo bordo viene stirato del {1} % durante la formatura (rischio di cricche); il ritaglio è qui un'approssimazione.",
"Kante {0}: das Laschenmaß {1} mm ist kleiner als die Biegung ({2} mm)":"Spigolo {0}: la misura della flangia {1} mm è inferiore alla piega ({2} mm)",
"Kante {0}: der Bogen ist zu eng für diese Lasche":"Spigolo {0}: l'arco è troppo stretto per questa flangia",
"Kante {0}: die Abstände lassen keine Lasche übrig.":"Spigolo {0}: le distanze non lasciano alcuna flangia.",
"Kante {0}: die Lasche kreuzt eine Biegelinie – mit „Abstand Anfang / Ende“ vor der Biegung enden lassen":"Spigolo {0}: la flangia incrocia una linea di piega – farla terminare prima della piega con «Distanza inizio / fine»",
"Kante {0}: die Lasche liegt in einer Biegezone":"Spigolo {0}: la flangia si trova in una zona di piega",
"Kante {0}: ein Ausschnitt gehört zu einer Lasche, die es nicht gibt.":"Spigolo {0}: un ritaglio appartiene a un'aletta che non esiste.",
"Kante {0}: ein Ausschnitt in der Lasche liegt {1} mm neben der Biegung (weniger als 2 × Blechdicke) – er verzieht sich beim Biegen.":"Spigolo {0}: un ritaglio nell'aletta si trova a {1} mm dalla piega (meno di 2 × lo spessore della lamiera) – si deforma durante la piegatura.",
"Kante {0}: ein Ausschnitt liegt {1} mm neben der Biegung (weniger als 2 × Blechdicke) – er verzieht sich beim Biegen.":"Spigolo {0}: un ritaglio si trova a {1} mm dalla piega (meno di 2 × lo spessore della lamiera): si deforma durante la piegatura.",
"Kante {0}: ein Ausschnitt ragt über die Lasche hinaus.":"Spigolo {0}: un ritaglio sporge oltre l'aletta.",
"Kante {0}{1}: Lasche {2} mm ist kürzer als 2 × Blechdicke – auf der Abkantpresse kaum zu biegen.":"Spigolo {0}{1}: la flangia di {2} mm è più corta di 2 × lo spessore della lamiera: difficilmente piegabile sulla pressopiegatrice.",
"Kante {0}{1}: Saum {2} mm ist kürzer als 4 × Blechdicke – er lässt sich schlecht zudrücken.":"Spigolo {0}{1}: l'orlo di {2} mm è più corto di 4 × lo spessore della lamiera – è difficile da schiacciare.",
"Kante {0}{1}: geschlossener Saum (Innenradius {2} mm) – wird in zwei Hüben gebogen und zugedrückt; harte Werkstoffe reißen dabei an der Außenseite.":"Spigolo {0}{1}: orlo chiuso (raggio interno {2} mm) – viene piegato in due colpi e schiacciato; i materiali duri si crepano sul lato esterno.",
"Kanten":"Spigoli",
"Kanten (Geraden deckungsgleich, Kreise mittig)":"Spigoli (rette coincidenti, cerchi concentrici)",
"Kanten abrunden: „Verrundung“ (F), einige Kanten anklicken, Radius z. B. 3 mm, OK.":"Arrotondare gli spigoli: «Raccordo» (F), fare clic su alcuni spigoli, raggio ad es. 3 mm, OK.",
"Kanten anklicken (erneut klicken entfernt).":"Cliccare gli spigoli (un nuovo clic li rimuove).",
