"Kugel-, Schaft-, Torus- oder Konusfräser. Ein Kugelfräser behält seine Bahn; andere Fräser werden geneigt und entlang ihrer Achse verschoben, bis sie am Teil anliegen, ohne es zu verletzen. Höchstens die größte Neigung; wo Schaft oder Halter das Teil berühren würden, richtet sich das Werkzeug auf. Ausgabe als Werkzeugvektor (Heidenhain, Sinumerik, Fanuc), sonst als 3-Achs-Bahn.":"Fresa sferica, cilindrica, toroidale o conica. Una fresa sferica mantiene il suo percorso; le altre frese vengono inclinate e spostate lungo il loro asse finché toccano il pezzo senza danneggiarlo. Al massimo l'inclinazione massima; dove il gambo o il portautensile toccherebbe il pezzo, l'utensile si raddrizza. Uscita come vettore utensile (Heidenhain, Sinumerik, Fanuc), altrimenti come percorso a 3 assi.",
