"Lasche an Lasche: Winkel + biegt in dieselbe Richtung weiter (U-Profil, Falz mit 180°), − in die Gegenrichtung (Z-Stufe, Hutprofil). Saum: der Rand der Lasche wird um 180° auf sich selbst zurückgelegt – offen mit einem Spalt von einer Blechdicke, geschlossen flach zugedrückt; mit − 180° liegt er auf der anderen Seite. Das Feld R ist der Innenradius nur dieser Biegung (leer = wie beim Blech). Für einen Saum direkt an der Plattenkante die Lasche selbst auf 180° stellen. Kröpfung: zwei Biegungen gegeneinander (− 45° und + 45°) – der Rand läuft parallel versetzt weiter; Versatz über die Länge des schrägen Stücks und die Winkel.":"Linguetta su linguetta: un angolo + continua a piegare nella stessa direzione (profilo a U, piega a 180°), − nella direzione opposta (gradino a Z, profilo a cappello). Orlo: il bordo della linguetta viene ripiegato di 180° su se stesso – aperto con una fessura pari a uno spessore di lamiera, chiuso schiacciato piatto; con − 180° si trova sull'altro lato. Il campo R è il raggio interno solo di questa piega (vuoto = come per la lamiera). Per un orlo direttamente sullo spigolo della piastra impostare la linguetta stessa a 180°. Sbalzo: due pieghe contrapposte (− 45° e + 45°) – il bordo prosegue parallelo e spostato; lo spostamento risulta dalla lunghezza del tratto obliquo e dagli angoli.",
"Lasche {0}":"Aletta {0}",
"Laschen, die über eine Biegelinie laufen, sind dort geteilt und freigestellt.":"Le flange che attraversano una linea di piega vengono lì divise e liberate.",
