"Länge L ist die Messlänge aus dem Werkzeug (Nennwert). Die echten Längen an der Maschine oder am Voreinstellgerät messen und eintragen. Heidenhain: Datei nach TNC:\\system\\tooltab kopieren, dann Werkzeugverwaltung → WERKZEUG IMPORT.":"La lunghezza L è la lunghezza di misura dell'utensile (valore nominale). Misurare le lunghezze reali sulla macchina o sul presetting e inserirle. Heidenhain: copiare il file in TNC:\\system\\tooltab, poi gestione utensili → TOOL IMPORT.",
