"Macht ein geschlossenes Netz hohl: eine Innenwand im Abstand der Wandstärke kommt dazu – spart Material und Druckzeit. Stellen, die dünner sind als zwei Wandstärken, überschneiden sich danach; für Harzdruck ein Ablaufloch mit „Boolesch“ abziehen.":"Rende cava una mesh chiusa: viene aggiunta una parete interna alla distanza dello spessore di parete – risparmia materiale e tempo di stampa. Le zone più sottili di due spessori di parete si sovrappongono poi; per la stampa a resina sottrarre un foro di scarico con «Booleano».",
