"Mehrere Schrupp- oder Schlichtdurchgänge gibt es nur als Bahn":"Più passate di sgrossatura o finitura esistono solo come percorso utensile",
"Mehrere Teile in einer Aufspannung":"Più pezzi in un piazzamento",
"Mehrere Zustellungen und Leerdurchgang gibt es nur als Bahn":"Più incrementi di passata e la passata a vuoto esistono solo come percorso utensile",
"Mehrere aneinanderhängende Kanten zählen als eine Strecke: Der Radius läuft vom Anfang der Kette bis zu ihrem Ende, Stützpunkte gelten in % der ganzen Kettenlänge. Das rechnet der große Geometriekern.":"Più spigoli consecutivi contano come un unico percorso: il raggio varia dall'inizio della catena alla sua fine, i punti di controllo sono in % della lunghezza totale della catena. Lo calcola il kernel geometrico completo.",
"Mehrfachaufspannung":"Più pezzi",
"Mehrfachaufspannung: Nullpunkt von Teil {0} gibt es an dieser Steuerung nicht – nur ein Teil ausgegeben":"Più pezzi: questo controllo non ha un'origine per il pezzo {0} – generato un solo pezzo",
"Mehrfachaufspannung: Nullpunktverschiebung gibt es in diesem Postprozessor nicht – „Eigener Nullpunkt je Teil“ wählen; nur ein Teil ausgegeben":"Più pezzi: questo postprocessore non ha lo spostamento origine – scegliere «Origine propria per pezzo»; generato un solo pezzo",
"Meine Designs · {0}":"I miei design · {0}",
"Meine Werkzeuge":"I miei utensili",
"Meldet Bahnen, die tiefer schneiden als das Modell an dieser Stelle (Schaft-, Plan-, Kugel- und Torusfräser, Fasenfräser und Bohrer mit ihrem Kegel; 3-Achs-Bewegungen). Ein Schnitt, der nicht im Modell steht – Gravur, Eckenfreistich, Tasche nur aus einer Skizze – wird ebenfalls gemeldet.":"Segnala i percorsi che tagliano più in profondità del modello in quel punto (frese cilindriche, a spianare, sferiche e toriche, frese per smussi e punte con il loro cono; movimenti a 3 assi). Viene segnalato anche un taglio che non è nel modello – incisione, scarico d'angolo, tasca ricavata solo da uno schizzo.",
"Meldung auf dem Bildschirm der Steuerung: Fanuc und LinuxCNC als (MSG, …), Sinumerik als MSG(\"…\"), sonst als Kommentar.":"Messaggio sullo schermo del controllo: Fanuc e LinuxCNC come (MSG, …), Sinumerik come MSG(\"…\"), altrimenti come commento.",
