"Noch kein Skript – eine .py-Datei oder einen Ordner laden.":"Nessuno script finora – caricare un file .py o una cartella.",
"Noch kein Wiederherstellungspunkt – der erste entsteht, sobald sich der Entwurf ändert und die eingestellte Zeit vergangen ist.":"Ancora nessun punto di ripristino – il primo viene creato quando il progetto cambia e il tempo impostato è trascorso.",
"Noch kein Zusatzmodul – einen Ordner mit Zusatzmodul laden.":"Nessun componente aggiuntivo finora – caricare una cartella con un componente aggiuntivo.",
