"Positiv = nach außen (mehr Material), negativ = nach innen. Ebene Flächen verschieben sich; bei einer Bohrung oder einem Zapfen ändert sich der Radius um den Abstand – eine Bohrung wird mit positivem Abstand enger.":"Positivo = verso l'esterno (più materiale), negativo = verso l'interno. Le facce piane si spostano; per un foro o un perno il raggio cambia della distanza – con distanza positiva un foro si restringe.",
