"Projizieren (J): Fläche oder Kante eines Körpers anklicken – ihr Abbild kommt in die Skizze":"Proietta (J): fare clic su una faccia o uno spigolo di un corpo – la sua proiezione viene aggiunta allo schizzo",
"Projizieren von Kanten und Flächen braucht einen Volumenkörper des Standardkerns – Körperumriss und Schnittkurven gehen auch bei Netzen.":"La proiezione di spigoli e facce richiede un solido del kernel standard; silhouette del corpo e curve di intersezione funzionano anche con le mesh.",
