"Prägen braucht einen Körper.":"Goffra richiede un corpo.",
"Prägung":"Goffratura",
"Prägung {0}: die Kontur ist schmaler als 2 × Blechdicke – es bleibt kein Hohlraum.":"Goffratura {0}: il contorno è più stretto di 2 × lo spessore della lamiera – non rimane alcuna cavità.",
"Prägung {0}: lässt sich so nicht formen":"Goffratura {0}: non può essere formata così",
"Prägung {0}: mit dieser Wandschräge lässt sie sich nicht formen":"Goffratura {0}: non può essere formata con questa inclinazione della parete",
"Prägung {0}: {1} mm ist höher als 3 × Blechdicke – mit senkrechter Wand reißt das Blech.":"Goffratura {0}: {1} mm supera 3 × lo spessore della lamiera – con parete verticale la lamiera si strappa.",
"Prägung: die Kontur wird nicht ausgeschnitten, sondern um die Höhe aus der Platte gedrückt; das zweite Feld ist die Wandschräge (0° = senkrecht). Senkprägung: der Rand einer runden Bohrung wird zu einem 90°-Kegel gedrückt – für Senkschrauben in dünnem Blech (− nach unten: Schraube von oben).":"Goffratura: il contorno non viene ritagliato, ma spinto fuori dalla piastra dell'altezza indicata; il secondo campo è l'inclinazione della parete (0° = verticale). Svasatura imbutita: il bordo di un foro tondo viene spinto in un cono a 90° – per viti a testa svasata in lamiera sottile (− verso il basso: vite dall'alto).",
