"Schraubstock, Spannpratzen oder Unterlage passend zum Rohteil als Körper anlegen und hier eintragen":"Creare morsa, staffe o piastra di appoggio come corpi adatti al grezzo e aggiungerli qui",
"Schraubstock: die Backen greifen quer zur X-Achse des Setups (an Y-min und Y-max des Rohteils); 0 = Größe und Spanntiefe passend wählen. Die Spannmittel werden einfache Körper am Ende der Zeitleiste und hier als Spannmittel eingetragen: Halter- und Kollisionsprüfung, Sicherheitsabstände und Einrichteblatt berücksichtigen sie.":"Morsa: le ganasce serrano trasversalmente all'asse X del setup (su Y-min e Y-max del grezzo); 0 = scegliere automaticamente dimensione e profondità di serraggio. Gli attrezzi di serraggio diventano corpi semplici alla fine della timeline e vengono aggiunti qui come attrezzi di serraggio: verifica portautensile e collisioni, distanze di sicurezza e foglio di attrezzaggio ne tengono conto.",
