"Simultan 4-achsig: Drehachse A entlang X durch die Rohteilmitte (Zylinder-Rohteil: dessen Achse). Der Kugelfräser steht radial zur Achse, A dreht das Teil. Nullpunkt Y/Z auf die Achse legen; nach der Bearbeitung fährt A auf ein Vielfaches von 360°.":"4 assi simultanei: asse di rotazione A lungo X attraverso il centro del grezzo (grezzo cilindrico: il suo asse). La fresa sferica è radiale rispetto all'asse, A ruota il pezzo. Posizionare l'origine pezzo Y/Z sull'asse; dopo la lavorazione A si porta a un multiplo di 360°.",
