"Sätze mit X/Y/Z und A zusammen: Der Vorschub steht in mm/min im Programm, viele Steuerungen rechnen dort aber Grad wie Millimeter – Einstellung „Vorschub mit Drehachse“ des Postprozessors auf „umgerechnet“ oder „zeitreziprok (G93)“ stellen":"Blocchi con X/Y/Z e A insieme: nel programma l'avanzamento è in mm/min, ma molti controlli lì contano i gradi come millimetri – impostare l'opzione «Avanzamento con asse rotativo» del postprocessore su «convertito» o «tempo inverso (G93)»",
