"Tasche auf dem Umfang aus den geschlossenen Konturen einer Skizze, die längs zur Drehachse liegt (innere Konturen bleiben als Inseln stehen). Die Skizze wird auf den Durchmesser gewickelt; ein angetriebener Schaftfräser, der zur Achse zeigt, räumt von innen nach außen (Z und C fahren gemeinsam; Fanuc: Zylinder-Interpolation G7.1). Der Fräser taucht auf einer Rampe entlang des innersten Rings ein.":"Tasca sulla circonferenza ricavata dai contorni chiusi di uno schizzo posto lungo l'asse di tornitura (i contorni interni restano come isole). Lo schizzo viene avvolto sul diametro; una fresa a candela motorizzata rivolta verso l'asse sgrossa dall'interno verso l'esterno (Z e C si muovono insieme; Fanuc: interpolazione cilindrica G7.1). La fresa penetra con una rampa lungo l'anello più interno.",
"Tasche bis zum Boden ausräumen":"Svuota una tasca fino al fondo",
"Tasche gespiegelt":"Tasca speculare",
"Tasche in den Mantel fräsen, die C-Achse dreht mit":"Fresa una tasca nella superficie cilindrica, l'asse C ruota insieme",
"Tasche in der Planfläche aus den geschlossenen Konturen einer Skizze (innere Konturen bleiben als Inseln stehen), mit einem angetriebenen Schaftfräser entlang Z. Geräumt wird von innen nach außen; der Fräser taucht auf einer Rampe entlang der innersten Bahn ein und bleibt innerhalb einer Ebene unten. X und C fahren gemeinsam (Fanuc: Polar-Interpolation G12.1). Tiefe ab Planfläche.":"Tasca nella faccia frontale dai contorni chiusi di uno schizzo (i contorni interni restano come isole), con una fresa a codolo motorizzata lungo Z. Lo svuotamento procede dall'interno verso l'esterno; la fresa entra in rampa lungo il percorso più interno e resta in basso entro un livello. X e C si muovono insieme (Fanuc: interpolazione polare G12.1). Profondità dalla faccia frontale.",
