"Tauchschruppen: senkrechte Tauchgänge Reihe für Reihe – für lange Werkzeuge und tiefe Kavitäten":"Sgrossatura a tuffo: tuffi verticali fila per fila – per utensili lunghi e cavità profonde",
"Teil 1 liegt normalerweise auf dem Nullpunkt (0, 0, 0). Die anderen werden mit einer Nullpunktverschiebung angefahren (Heidenhain Zyklus 7, Fanuc/LinuxCNC G52, Sinumerik TRANS). Vor jedem Wechsel geht das Werkzeug auf die sichere Höhe.":"Il pezzo 1 di norma è sullo zero (0, 0, 0). Gli altri vengono raggiunti con uno spostamento origine (Heidenhain ciclo 7, Fanuc/LinuxCNC G52, Sinumerik TRANS). Prima di ogni cambio l'utensile sale all'altezza di sicurezza.",
