"Teilt Kanten, die länger sind, in der Mitte (je Durchgang einmal) – die Form bleibt gleich. 0 teilt jede Kante: jedes Dreieck wird zu vier. Sinnvoll vor dem Glätten grober Netze.":"Divide a metà gli spigoli più lunghi (una volta per passata): la forma resta invariata. 0 divide ogni spigolo: ogni triangolo diventa quattro. Utile prima di levigare mesh grossolane.",
