"Toleranzwert, dahinter die Bezüge (durch Leerzeichen getrennt), z. B. Ø0,05 A B. Zusätze in Klammern werden als Buchstabe im Kreis gezeichnet: Ø0,05(M) A(M) – (M) Maximum-Material, (L) Minimum-Material, (P) projiziert, (F) freier Zustand, (E) Hüllbedingung":"Valore di tolleranza seguito dai riferimenti (separati da spazi), ad es. Ø0,05 A B. Le aggiunte tra parentesi vengono disegnate come lettera in un cerchio: Ø0,05(M) A(M) – (M) massimo materiale, (L) minimo materiale, (P) proiettata, (F) stato libero, (E) requisito di inviluppo",
