"Vernetzung fehlgeschlagen:":"Mesh non riuscita:",
"Verrechnet zwei geschlossene Netze wirklich miteinander: innen liegende Flächen verschwinden, die Schnittkanten werden neu vernetzt. Gerechnet wird nur dort, wo sich die beiden Netze begegnen können – ein großes Netz mit einem kleinen Eingriff geht deshalb schnell. Überlappen zwei große Netze ganz, vorher „Reduzieren“.":"Combina davvero due mesh chiuse: le facce interne scompaiono e gli spigoli di intersezione vengono rimagliati. Il calcolo avviene solo dove le due mesh possono incontrarsi, quindi una mesh grande con un piccolo intervento è veloce. Se due mesh grandi si sovrappongono completamente, usare prima «Riduci».",
