"Verschiebt jede Fläche um den Abstand nach außen (negativ: nach innen) – für Spiel, Aufmaß oder ein Negativ. Kanten und Ecken bleiben scharf; sehr feine Stellen können sich beim Schrumpfen überschneiden.":"Sposta ogni faccia verso l'esterno della distanza indicata (negativa: verso l'interno) – per gioco, sovrametallo o un negativo. Spigoli e angoli restano vivi; i dettagli molto fini possono sovrapporsi durante il restringimento.",
