"Verschleiß":"Usura",
"Verschraubung: Scheiben und Mutter kommen mit der Schraube in einem Zug an jede angeklickte Bohrung. Die Klemmdicke ist die Länge der Bohrung – durch mehrere Teile hindurch, wenn ihre Bohrungen fluchten und aneinanderstoßen. Mit Mutter wird die kürzeste Vorzugslänge vorgeschlagen, bei der die Schraube zwei Gewindegänge aus der Mutter ragt.":"Collegamento a vite: le rondelle e il dado vengono inseriti insieme alla vite, in un'unica operazione, su ogni foro selezionato. Lo spessore serrato è la lunghezza del foro – attraverso più pezzi se i loro fori sono allineati e contigui. Con il dado viene proposta la lunghezza preferenziale più corta con cui la vite sporge di due filetti dal dado.",
