"Verschraubung: {0} – {1}; die Schraube ist für die Klemmdicke {2} mm zu kurz (nötig: {3} mm)":"Collegamento a vite: {0} – {1}; la vite è troppo corta per lo spessore serrato di {2} mm (necessario: {3} mm)",
