"Wickelt die Skizzenkurven auf den Zylinder: X bleibt X, der Abstand quer zur Achse wird zum Bogen auf dem Abwicklungs-Ø (Drehung A). Die Skizze muss parallel zur A-Achse liegen, z. B. auf einer Tangentialebene. Gefräst wird in fester Tiefe unter der Teiloberfläche – für Gravuren, Schriften und Nuten rund um das Teil.":"Avvolge le curve dello schizzo sul cilindro: X resta X, la distanza trasversale all'asse diventa un arco sul Ø di sviluppo (rotazione A). Lo schizzo deve essere parallelo all'asse A, ad es. su un piano tangente. Si fresa a profondità fissa sotto la superficie del pezzo: per incisioni, scritte e cave attorno al pezzo.",
"Wie 3D-Kontur, aber das Werkzeug fährt ohne Absätze kontinuierlich nach unten – keine Eintauchmarken an steilen Wänden.":"Come il contorno 3D, ma l'utensile scende in modo continuo senza gradini: nessun segno di affondamento sulle pareti ripide.",
"Wie Einfahrt":"Come l'ingresso",
"Wie ausgewählt":"Come selezionato",
"Wie die Ansicht":"Come la vista",
"Wie die Ansicht (alle Dreiecke)":"Come la vista (tutti i triangoli)",
"Wie fein Körper für STL, 3MF und den Slicer in Dreiecke zerlegt werden: Abweichung von der wahren Fläche als Anteil der Körpergröße. Netze bleiben, wie sie sind.":"Quanto finemente i corpi vengono suddivisi in triangoli per STL, 3MF e lo Slicer: scostamento dalla superficie reale come frazione della dimensione del corpo. Le mesh restano invariate.",
"Wie fein Zylinder, Kugeln und Rundungen in der Ansicht aus Dreiecken bestehen. Feiner sieht runder aus, rechnet bei großen Modellen aber länger. Der Export hat eine eigene Einstellung (3D-Druck).":"Quanto finemente cilindri, sfere e raccordi sono composti di triangoli nella vista. Più fine appare più rotondo, ma richiede più calcolo nei modelli grandi. L'esportazione ha una propria impostazione (stampa 3D).",
"Wie im System":"Come nel sistema",
"Wie lange die Schneide schneiden darf, bevor sie getauscht wird. Das Fenster „Bearbeitungszeit“ rechnet daraus, wie viele Teile noch möglich sind.":"Per quanto tempo il tagliente può tagliare prima di essere sostituito. La finestra «Tempo di lavorazione» ne ricava quanti pezzi sono ancora possibili.",
