"Zahnbreite (0 = aus der Kette)":"Larghezza del dente (0 = dalla catena)",
"Zahnform nach Tredgold (Ersatz-Stirnrad auf dem Rückenkegel), gerade Zähne. Das große Ende liegt in der Grundebene, die Zähne laufen zur Kegelspitze. Für Darstellung, 3D-Druck und Fräsen aus dem Vollen; geschliffene Kegelräder brauchen die Daten des Herstellers.":"Profilo del dente secondo Tredgold (ruota cilindrica equivalente sul cono complementare), denti diritti. L'estremità grande giace nel piano di base, i denti convergono verso il vertice del cono. Per rappresentazione, stampa 3D e fresatura dal pieno; le ruote coniche rettificate richiedono i dati del costruttore.",
"Zahnrad: Stirnrad gerade / schräg / Pfeil, Hohlrad, Zahnstange, Kegelrad, Schnecke, Schneckenrad, Kettenrad":"Ruota dentata: cilindrica a denti diritti / elicoidali / a freccia, corona interna, cremagliera, ruota conica, vite senza fine, ruota per vite senza fine, pignone per catena",
