"Zum Vereinen braucht es zwei Netzkörper.":"Per unire servono due corpi mesh.",
"Zungen stehen am freien Ende der Lasche über und kommen in den Zuschnitt. „Schlitze als Skizze“ legt die passenden Schlitze dort an, wo die Zungen stehen – je Ebene eine Skizze, jeder Schlitz ringsum um das Spiel größer als die Zunge. In dieser Skizze den Umriss des Gegenstücks zeichnen und daraus ein Blech oder eine Extrusion machen: die Schlitze werden Ausschnitte. Das Gegenstück liegt auf den Laschenenden auf; die Zungenlänge ist üblich gleich seiner Dicke.":"Le linguette sporgono all'estremità libera dell'aletta ed entrano nello sviluppo grezzo. «Asole come schizzo» crea le asole corrispondenti dove si trovano le linguette – uno schizzo per piano, con ogni asola più grande della linguetta del gioco su tutto il contorno. In questo schizzo disegnare il contorno del pezzo di accoppiamento e ricavarne una lamiera o un'estrusione: le asole diventano tagli. Il pezzo di accoppiamento poggia sulle estremità delle alette; la lunghezza delle linguette è di solito uguale al suo spessore.",
