"Zwischen zwei Schnitten hebt das Werkzeug nur so weit ab, wie das Material auf dem Weg es verlangt (Rohteil abzüglich allem, was dieses Setup bis dahin gefräst hat) plus Sicherheitsabstand – und beginnt den Vorschub erst dort.{0}{1}":"Tra due passate l'utensile si solleva solo quanto richiede il materiale lungo il percorso (grezzo meno tutto ciò che questo setup ha fresato fino a quel punto) più la distanza di sicurezza, e inizia l'avanzamento solo da lì.{0}{1}",
