"Übernehmen":"Applica",
"Übernommen werden Skizzen, Extrusion, Rotation, Bohrung, Verrundung, Fase und Schale als eigene Schritte der Zeitachse. Für alles andere legt das Skript den Stand des Modells als STEP bei, sodass die Form stimmt.":"Schizzi, estrusione, rivoluzione, foro, raccordo, smusso e guscio vengono importati come passi propri della timeline. Per tutto il resto lo script allega lo stato del modello come STEP, in modo che la forma sia corretta.",
