"„+“ = Werkzeug wird neu angelegt. Schnittdaten sind Richtwerte für Hartmetall ({0}){1}; Kühlung: {2}.":"«+» = l'utensile verrà creato. I dati di taglio sono valori indicativi per metallo duro ({0}){1}; refrigerante: {2}.",
"„Ineinander schachteln“ legt die Zuschnitte in die Lücken und Buchten ihrer Nachbarn und in deren Ausschnitte (ohne 90°-Drehen nur um 180° gewendet); der Abstand wird nie unterschritten. Ohne den Haken liegen sie nach ihrem umschließenden Rechteck in Reihen. Mit „Skizze + Körper“ entstehen flache Körper in Blechdicke, die sich in der Fertigung mit 2D-Kontur ausschneiden lassen.":"«Annida i ritagli» dispone i ritagli negli spazi e nelle rientranze dei vicini e nei loro ritagli (senza rotazione di 90°, solo capovolti di 180°); la distanza non viene mai ridotta. Senza la spunta vengono disposti in file secondo il rettangolo che li racchiude. Con «Schizzo + corpi» si ottengono corpi piatti dello spessore della lamiera, che in produzione si possono tagliare con un contorno 2D.",
"„Innen/Außen“ braucht geschlossene Konturen – offene Kurven mit „Auf der Kurve“ fräsen":"«Interno/Esterno» richiede profili chiusi – fresare le curve aperte con «Sulla curva»",
"„Prüfen“ fährt den Ablauf in kleinen Zeitschritten ab und meldet, wann welche Körper zusammenstoßen.":"«Verifica» percorre la sequenza a piccoli intervalli di tempo e segnala quando e quali corpi entrano in collisione.",
"„Skizze fertig“ → Extrusion, Rotation oder Bohrung.":"«Termina schizzo» → Estrusione, Rivoluzione o Foro.",
"„Skizze“ → Ebene XY/XZ/YZ wählen oder eine ebene Fläche anklicken.":"«Schizzo» → scegliere il piano XY/XZ/YZ oppure cliccare una faccia piana.",
