"⚠ Jedes NC-Programm vor dem ersten Lauf prüfen: an der Maschine im Probelauf (Einzelsatz, reduzierter Eilgang) oder in einem externen NC-Simulator. Die Simulation hier ersetzt das nicht – Nutzung auf eigene Gefahr, ohne Gewährleistung.":"⚠ Verificare ogni programma NC prima della prima esecuzione: sulla macchina in prova a vuoto (blocco singolo, rapido ridotto) o in un simulatore NC esterno. La simulazione qui non lo sostituisce – uso a proprio rischio, senza garanzia.",
