"⚠ Nach der letzten Änderung des Körpers war nicht eindeutig, welche Kante oder Fläche gemeint ist. Bitte prüfen – bei Bedarf löschen und neu projizieren.":"⚠ Dopo l’ultima modifica del corpo non era chiaro a quale spigolo o faccia ci si riferisse. Verificare – se necessario eliminare e proiettare di nuovo.",
"⚠ Programmlogik (JavaScript) wird nicht ausgeführt: Sonderfunktionen, 4./5. Achse, Messzyklen und Maschinenoptionen bitte im Postprozessor-Editor prüfen.":"⚠ La logica di programma (JavaScript) non viene eseguita: verificare funzioni speciali, 4º/5º asse, cicli di misura e opzioni macchina nell'editor del postprocessore.",
